importedTypeDeclarations.text:
export interface SagaTreeFaceAnchorBarycentric {
  readonly u: number;
  readonly v: number;
  readonly w: number;
}

export interface SagaTreeFaceAnchorTriangleBinding {
  readonly nodeIdentity: string;
  readonly primitiveIndex: number;
  readonly triangleIndex: number;
  readonly barycentric: SagaTreeFaceAnchorBarycentric;
}

export interface SagaTreeFaceAnchorsManifestV1 {
  readonly contractVersion: typeof FACE_ANCHORS_CONTRACT_VERSION;
  readonly anchors: Readonly<Partial<Record<SagaTreeFaceAnchorId, SagaTreeFaceAnchorTriangleBinding>>>;
}

export interface SagaTreeFaceAnchorBindingValidationIssue {
  readonly code:
    | 'invalid_anchor_id'
    | 'invalid_node_identity'
    | 'invalid_primitive_index'
    | 'invalid_triangle_index'
    | 'invalid_barycentric'
    | 'contract_version_mismatch';
  readonly anchorId?: SagaTreeFaceAnchorId;
  readonly detail: string;
}

export interface SagaTreeFaceAnchorBindingValidationResult {
  readonly ok: boolean;
  readonly issues: readonly SagaTreeFaceAnchorBindingValidationIssue[];
}

export interface AvatarMorphParamMeta {
  key: AvatarMorphParamKey;
  group: AvatarMorphParamGroup;
  labelDe: string;
  min: -1;
  max: 1;
  default: 0;
  step: number;
}

export interface AvatarMorphColorsV1 {
  skin: string;
  eyes: string;
  hair: string;
}

export interface AvatarMorphTraitSlotsV1 {
  markings: readonly string[];
  scars: readonly string[];
  cybernetics: readonly string[];
}

export interface SagaTreeAvatarMorphStateV1 {
  contractVersion: typeof MORPH_CONTRACT_VERSION;
  body: AvatarMorphBodyValues;
  face: AvatarMorphFaceValues;
  colors: AvatarMorphColorsV1;
  traits: AvatarMorphTraitSlotsV1;
}

export interface AvatarMorphCapabilities {
  flags: readonly AvatarMorphCapabilityFlag[];
}

export interface AvatarMorphValidationResult {
  ok: boolean;
  state: SagaTreeAvatarMorphStateV1;
  /** Unknown keys that were ignored (fail-safe). */
  ignoredKeys: readonly string[];
  /** Human-readable DE reasons when values were clamped/rejected. */
  warnings: readonly string[];
}

export interface CharacterAttributesDto {
  strength: number;
  dexterity: number;
  endurance: number;
  mind: number;
  perception: number;
  charisma: number;
}

export interface CharacterAttributeStorageDto extends Partial<CharacterAttributesDto> {
  constitution?: number;
  intelligence?: number;
  wisdom?: number;
}

export interface CharacterAvatarDto {
  schema_version: 1;
  /** @deprecated Prefer `source`. Kept for legacy readers; always `m3-character-studio`. */
  provider: 'm3-character-studio';
  /**
   * Avatar origin — never a capability proof (#6 owns capabilities).
   * Missing → resolve via resolveAvatarSource (legacy provider → sagatree).
   */
  source?: 'sagatree' | 'import' | 'meshy';
  preset: string;
  model_format: CharacterAvatarFormat;
  model_url?: string;
  traits: { head?: string; ears?: string; hair?: string; clothing?: string; accessory?: string };
  /** hair/skin required for legacy; eyes optional until morph migration. */
  colors: { hair: string; skin: string; eyes?: string };
  body: { height: number; size: number };
  morph_contract_version?: 'SagaTreeAvatarMorphV1';
  /** Validated morph state — prefer morph-contract helpers over raw writes. */
  morph?: SagaTreeAvatarMorphStateV1;
  /**
   * Avatar V2 template ingress (#260) — optional; ignored by legacy readers.
   * `template_id` e.g. `species-template:dwarf`; `body_family` from template pack.
   */
  template_id?: string;
  body_family?: 'standard' | 'compact' | 'heavy' | 'custom';
  /** V2 anatomy; legacy `non-humanoid` still readable via composition mapper. */
  anatomy?: 'humanoid' | 'custom-creature' | 'non-humanoid' | 'unknown';
  body_compatibility?: 'standard' | 'compact' | 'heavy' | 'custom' | 'unknown';
  /** V2 modularity; legacy `none` maps to monolithic. */
  modularity?: 'modular-parts' | 'limited' | 'monolithic' | 'none';
  /** Logical starter wardrobe ids applied as basic outfit (not inventory). */
  starter_wardrobe?: readonly string[];
  /**
   * Manual Face Mapping bindings for this character (#persist).
   * SagaTreeFaceAnchorsV1 — mesh triangle anchors only; never webcam landmarks.
   * Optional; ignored by legacy readers. Wins over sibling face-anchors.json sidecar.
   */
  face_anchors?: SagaTreeFaceAnchorsManifestV1;
}

export interface CharacterAppearanceDto {
  body_size: number;
  height: number;
  face_features: string;
  hair_style: string;
  hair_color: string;
  skin_tone: string;
  clothing: string;
  gender_reading?: CharacterGenderReading;
  avatar?: CharacterAvatarDto;
  /**
   * Optional personal LookProfile override for player-character resolution (#347).
   * Null/omitted → inherit saga/session/system. Must be active + owned when set.
   */
  personal_look_profile_id?: string | null;
}

export interface AbilityDto {
  id: string;
  name: string;
  description: string;
  type: 'combat' | 'magic' | 'skill';
  cost: number;
  effect: string;
  source?: string;
  rank?: 'I' | 'II' | 'III' | 'IV' | 'V';
  action_type?: 'Passiv' | 'Hauptaktion' | 'Bewegung' | 'Reaktion';
  tags?: string[];
  usage_limit?: string;
}

export interface ItemDto {
  id: string;
  name: string;
  description: string;
  type: ItemType;
  quantity: number;
  load?: 0 | 1 | 2 | 3;
  cost?: 0 | 1 | 2 | 3 | 4 | 5;
  damage?: string;
  damage_type?: string;
  protection?: 1 | 2 | 3;
  minimum_strength?: 1 | 2 | 4;
  traits?: string[];
}

export interface EmotionProfileDto {
  id: string;
  name: string;
  intensity: number;
}

export interface SagaTreeSpecializationDto {
  skill: SagaTreeSkillKey;
  name: string;
  source?: SagaTreeSpecializationSource;
  acquiredAtLevel?: number;
}

export interface SagaTreeBackgroundDto {
  name: string;
  skillPool: SagaTreeSkillKey[];
  /** Derived from backgroundSkillPoints for UI compatibility — not a skill-progression source of truth. */
  trainedSkills: SagaTreeSkillKey[];
  backgroundSkillPoints?: SagaTreeBackgroundSkillPoints;
  specialization?: SagaTreeSpecializationDto;
  milieuAccess: string;
  contact: string;
  complication: string;
  communication: string;
}

export interface SagaTreeSpeciesTraitInstanceDto {
  trait: SagaTreeSpeciesTraitKey;
  option?: SagaTreeSpeciesTraitOptionKey;
  legacyDetail?: string;
  source: SagaTreeSpeciesTraitSource;
  acquiredAtLevel: number;
}

export interface SagaTreeSpeciesProfileDto {
  name: string;
  bodyDescription: string;
}

export interface SagaTreeProfileDto {
  archetype?: SagaTreeArchetypeKey;
  essence?: SagaTreeEssenceKey;
  speciesTraitInstances: SagaTreeSpeciesTraitInstanceDto[];
  speciesTraits?: SagaTreeSpeciesTraitKey[];
  speciesTraitDetails?: SagaTreeSpeciesTraitDetailsDto;
  speciesProfile?: SagaTreeSpeciesProfileDto;
  backgroundTemplateId?: string | null;
  background: SagaTreeBackgroundDto;
  archetypeTrainingSkill?: SagaTreeSkillKey;
  freeSkillRanks?: Partial<Record<SagaTreeSkillKey, number>>;
  skillAdvances?: SagaTreeSkillAdvanceDto[];
  specializations?: SagaTreeSpecializationRecordDto[];
  baseAttributes?: CharacterAttributesDto;
  attributeAdvances?: SagaTreeAttributeAdvancesDto;
  presetReleaseMode?: SagaTreePresetReleaseMode;
  drive: number;
  momentum: number;
}

export interface WorldProfileBinding {
  /** World profile bound by the adventure the character is attached to. */
  adventureWorldProfileId?: string | null;
  /** World profile bound by the character itself. */
  characterWorldProfileId?: string | null;
}

export interface CatalogDefinitionRecord {
  definition: ItemDefinition;
  status: CatalogDefinitionStatus;
  /** Immutable public item id (IT-XXXXX) when persisted. */
  publicId?: string | null;
  /** Set exactly for `world` definitions. */
  worldProfileId?: string | null;
  /** Set for `personal` definitions; the authenticated owner. */
  ownerUserId?: string | null;
}

export interface CatalogVisibilityContext {
  userId: string;
  effectiveWorldProfileId: string | null;
}

export interface CatalogMutationContext {
  userId: string;
  /** World profiles the caller may edit. Empty ⇒ no World writes. */
  editableWorldProfileIds: readonly string[];
}

export interface MigratedPersonalDefinitionDraft {
  /** Temporary key used inside the migration result before a stable id is assigned. */
  fingerprint: string;
  name: string;
  description: string;
  type: InventoryItemType;
  load: ItemDefinition['load'];
  cost: ItemDefinition['cost'];
  stackLimit: number;
  damage?: string;
  damageType?: string;
  protection?: ItemDefinition['protection'];
  requirements?: ItemDefinition['requirements'];
  traits?: string[];
}

export interface LegacyMigrationResult {
  state: InventoryState;
  /** Unique Personal drafts that must exist before the state is marked v2. */
  personalDrafts: MigratedPersonalDefinitionDraft[];
  /**
   * Maps each temporary instance `definitionId` of the form `pending:<fingerprint>`
   * (or an already-resolved Core id) so the persistence layer can rewrite
   * pending references to stable `personal:<uuid>` ids after insert.
   */
  pendingDefinitionKeys: string[];
}

interface NormalizedLegacy {
  name: string;
  description: string;
  type: InventoryItemType;
  quantity: number;
  load: 0 | 1 | 2 | 3;
  cost: 0 | 1 | 2 | 3 | 4 | 5;
  damage?: string;
  damageType?: string;
  protection?: 1 | 2 | 3;
  minimumStrength?: 1 | 2 | 4;
  traits: string[];
}

export type SplitDestination =
  | { kind: 'base'; slotIndex: number }
  | { kind: 'container'; containerInstanceId: string; positionIndex: number };

export interface ItemMechanics {
  damage?: string;
  damageType?: string;
  protection?: ItemProtection;
  traits?: string[];
}

export interface ItemRequirements {
  minimumStrength?: MinimumStrength;
}

export interface ItemInstance {
  /** Unique within one character's inventory state. */
  instanceId: string;
  definitionId: string;
  /** Units in this stack; always >= 1. */
  quantity: number;
  /** Absent when the instance is a pure definition mirror. */
  state?: ItemInstanceState;
}

export type InventoryLocation =
  | { kind: 'base'; slotIndex: number }
  | { kind: 'container'; containerInstanceId: string; positionIndex: number }
  | { kind: 'equipment'; slot: EquipmentSlot }
  | { kind: 'overflow' };

export interface InventoryState {
  schemaVersion: number;
  /** Instance records by instance id. */
  instances: Record<string, ItemInstance>;
  /** Exactly `BASE_SLOT_COUNT` ordered positions; `null` = explicitly empty. */
  baseSlots: (string | null)[];
  containers: ContainerContentsMap;
  equipment: EquipmentMap;
  /** Exactly `QUICK_SLOT_COUNT` ordered references; `null` = unassigned. */
  quickSlots: (string | null)[];
  /** Legacy overflow — read/repair only, counts toward load, nothing is ever deleted into it. */
  legacyOverflow: string[];
}

export type InventoryOperationResult =
  | { ok: true; state: InventoryState }
  | { ok: false; error: InventoryOperationError; reason: string };

export interface InventoryInvariantFinding {
  code: InventoryInvariantCode;
  /** Instance id, slot name or index that triggered the finding. */
  detail: string;
}

export interface InventoryValidationReport {
  ok: boolean;
  findings: InventoryInvariantFinding[];
}

export interface InventoryNormalizationResult {
  state: InventoryState;
  repairs: InventoryInvariantFinding[];
  /** Instance ids kept in the state whose `definitionId` the catalog does not know. */
  unresolved: string[];
}

export interface InventoryPlacement {
  instanceId: string;
  location: InventoryLocation;
}

interface NormalizationContext {
  instances: Record<string, ItemInstance>;
  claimed: Set<string>;
  repairs: InventoryInvariantFinding[];
  unresolved: string[];
  lookup: ItemDefinitionLookup;
}

export interface ItemThumbnailAssetRecord {
  id: string;
  kind: ItemThumbnailKind;
  definitionId: string;
  ownerUserId: string;
  worldProfileId: string | null;
  mime: ItemThumbnailMime;
  byteSize: number;
  storagePath: string;
  origin: ItemThumbnailOrigin;
  createdAt: string;
}

export interface ItemThumbnailPromptInput {
  name: string;
  description: string;
  setting?: string;
  kindKey?: string;
  userExtra?: string;
}

export interface ItemDefinition extends ItemMechanics {
  /** Stable catalog id, e.g. `core:shortsword`. */
  id: string;
  /**
   * Immutable public item id (IT-XXXXX). Persisted Personal/World rows get it
   * from the DB trigger; Core/builtin Library rows may carry a derived stable id.
   * Never stored inside the JSON payload.
   */
  publicId?: string;
  scope: ItemDefinitionScope;
  name: string;
  description: string;
  type: InventoryItemType;
  load: ItemLoad;
  cost: ItemCost;
  /** Maximum units per stack; `1` means non-stackable. */
  stackLimit: number;
  requirements?: ItemRequirements;
  /** Equipment positions this definition may occupy. Absent/empty = not equippable. */
  equipSlots?: EquipmentSlot[];
  /** A two-handed item is one instance occupying both hand references. */
  twoHanded?: boolean;
  /** Capacity positions of a container definition; required when `type === 'container'`. */
  containerCapacity?: number;
  /** Future-facing visual metadata. Library/Inventory use assetKey only — never model3d. */
  iconKey?: string;
  assetKey?: string;
  /** Optional Workbench 3D GLB key (`model3d:{uuid}`). Display-only; not used as thumbnail. */
  model3d?: string;

  /** Semantic kind — may diverge from `type` (e.g. kindKey=device with type=tool). */
  kindKey?: ItemKindKey;
  /** Setting filters/recommendations; not a usage ban. */
  settingTags?: ItemSettingTag[];
  techLevel?: ItemTechLevel;
  contexts?: ItemContext[];
  capabilities?: ItemCapability[];
  roles?: ItemRole[];
  /** Provenance; Core catalog normalizes to `core-archetype`. */
  origin?: ItemOrigin;
  /** Optional parent archetype id — reference only, no runtime inheritance. */
  basedOnDefinitionId?: string;
}

export type ItemIconGenerationStatus =
  | 'needs-png'
  | 'needs-svg'
  | 'ready'
  | 'regenerate';

export interface ItemIconManifestEntry {
  id: string;
  slug: string;
  name: string;
  /** Short object description appended to the shared style template. */
  iconPrompt: string;
  /** Definition `iconKey` — same as slug for static SVG icons. */
  iconKey: string;
  /** Repo-relative PNG source path. */
  sourcePng: string;
  /** Repo-relative SVG output path. */
  outputSvg: string;
  /**
   * `ready` — valid SVG exists; do not auto-regenerate.
   * `regenerate` — explicit re-vectorize / re-generate allowed.
   * `needs-png` / `needs-svg` — incomplete pipeline.
   */
  status: ItemIconGenerationStatus;
}

export interface ItemIconPromptInput {
  name: string;
  /** Object-only description (no style boilerplate). */
  iconPrompt: string;
}

export interface ItemLibraryFilters {
  kinds: readonly ItemKindKey[];
  settings: readonly ItemSettingTag[];
  contexts: readonly ItemContext[];
  sources: readonly LibraryItemSource[];
  packIds: readonly string[];
}

export interface ItemModel3dAssetRecord {
  id: string;
  kind: ItemModel3dKind;
  definitionId: string;
  ownerUserId: string;
  worldProfileId: string | null;
  mime: ItemModel3dMime;
  byteSize: number;
  storagePath: string;
  origin: ItemModel3dOrigin;
  createdAt: string;
}

export interface ItemPack {
  /** Stable pack id, e.g. `builtin:fantasy-basic`. */
  id: string;
  /** Integer pack version — bump when membership or metadata changes. */
  version: number;
  name: string;
  description: string;
  /** Setting filters/recommendations; not a usage ban. */
  settingTags: readonly ItemSettingTag[];
  /** Definition ids in this pack (order is declaration order). */
  definitionIds: readonly string[];
}

export interface StandardItemInput {
  id: string;
  name: string;
  description: string;
  settingTags: readonly ItemSettingTag[];
  techLevel: ItemTechLevel;
  contexts?: readonly ItemContext[];
  capabilities?: readonly ItemCapability[];
  roles?: readonly ItemRole[];
  kindKey?: ItemKindKey;
  /** When set, mechanical fields are copied from CORE_MECHANIC_SNAPSHOTS. */
  basedOnDefinitionId?: string;
  /** Required when basedOnDefinitionId is absent (narrative-only item). */
  type?: InventoryItemType;
  load?: ItemLoad;
  cost?: ItemCost;
  stackLimit?: number;
  requirements?: ItemRequirements;
  equipSlots?: EquipmentSlot[];
  twoHanded?: boolean;
  containerCapacity?: number;
  damage?: string;
  damageType?: string;
  protection?: ItemDefinition['protection'];
  traits?: string[];
  /**
   * Static SVG slug under `/assets/items/{iconKey}.svg`.
   * Defaults to definition id with dots → hyphens (`builtin.fantasy.longsword` → `builtin-fantasy-longsword`).
   */
  iconKey?: string;
}

export interface CoreMechanicSnapshot extends ItemMechanics {
  type: InventoryItemType;
  load: ItemLoad;
  cost: ItemCost;
  stackLimit: number;
  requirements?: ItemRequirements;
  equipSlots?: EquipmentSlot[];
  twoHanded?: boolean;
  containerCapacity?: number;
}

export type ItemDefinitionMetadataValidation =
  | { ok: true }
  | { ok: false; errors: string[] };

export interface ItemCatalogModuleConfig {
  enabledPackIds: string[];
  includedDefinitionIds: string[];
  excludedDefinitionIds: string[];
  /** When false, personal definitions are omitted from new add-catalogs. Default true. */
  allowPersonalItems: boolean;
}

export interface ItemCatalogModuleDiagnosis {
  /** Pack ids preserved in config but not found in the known pack catalog. */
  unknownPackIds: readonly string[];
  /** Include ids preserved but not resolvable via the provided lookup. */
  unknownIncludedDefinitionIds: readonly string[];
  /** Exclude ids preserved but not resolvable (still applied by id when resolving). */
  unknownExcludedDefinitionIds: readonly string[];
  /** Fields that were missing or wrong-typed and coerced to defaults. */
  coercedFields: readonly string[];
}

export interface NormalizeItemCatalogModuleResult {
  config: ItemCatalogModuleConfig;
  diagnosis: ItemCatalogModuleDiagnosis;
}

export interface ResolveWorldItemCatalogInput {
  config: ItemCatalogModuleConfig;
  /** Core archetypes — always present; excludes of these ids are ignored. */
  coreDefinitions: readonly ItemDefinition[];
  /**
   * Resolves pack members and explicit includes (builtin-standard, world, …).
   * Core ids may also resolve here; Core list is still unioned explicitly.
   */
  resolveDefinition: (definitionId: string) => ItemDefinition | undefined;
  /** Pack catalog; defaults to ALL_ITEM_PACKS. Unknown pack ids are skipped with diagnosis. */
  packs?: readonly ItemPack[];
  /** World-scoped definitions for this world — always appended after excludes. */
  worldDefinitions?: readonly ItemDefinition[];
  /** Personal definitions — appended only when allowPersonalItems is true. */
  personalDefinitions?: readonly ItemDefinition[];
}

export interface ItemCatalogResolveDiagnosis {
  unknownPackIds: readonly string[];
  unresolvedIncludedDefinitionIds: readonly string[];
  ignoredCoreExcludeIds: readonly string[];
}

export interface ResolvedWorldItemCatalog {
  definitions: readonly ItemDefinition[];
  diagnosis: ItemCatalogResolveDiagnosis;
}

export interface ComposeCharacterInventoryAddCatalogInput {
  /** Adventure > Character > null — null means Core + Personal only (no packs). */
  effectiveWorldProfileId: string | null;
  /** World `item-catalog` module; defaults apply when module missing. Ignored if no world. */
  config: ItemCatalogModuleConfig;
  coreDefinitions: readonly ItemDefinition[];
  resolveDefinition: (definitionId: string) => ItemDefinition | undefined;
  packs?: readonly ItemPack[];
  worldDefinitions?: readonly ItemDefinition[];
  personalDefinitions?: readonly ItemDefinition[];
}

export type AssetProfileId =
  | 'character-portrait'
  | 'map-pin'
  | 'look-reference'
  | 'item-thumbnail'
  | 'user-avatar';

export type MediaByteBudget = {
  readonly targetBytes: number;
  readonly maxUploadBytes: number;
};

export type MediaOptimizeInputMeta = {
  readonly kind: MediaKind;
  readonly profileId: AssetProfileId;
  readonly mimeType: string;
  readonly byteSize: number;
  readonly width?: number;
  readonly height?: number;
  /** True when source is an animated GIF (or similar) that must not be silently flattened. */
  readonly hasAnimation?: boolean;
  /** True when source has an alpha channel that policy must preserve. */
  readonly hasAlpha?: boolean;
};

type MediaOptimizeResultBase = {
  readonly kind: MediaKind;
  readonly profileId: AssetProfileId;
  readonly input: MediaOptimizeInputMeta;
};

export type MediaOptimizeOptimizedResult = MediaOptimizeResultBase & {
  readonly status: 'optimized';
  readonly outputMimeType: string;
  readonly outputByteSize: number;
  readonly width?: number;
  readonly height?: number;
};

export type MediaOptimizeUnchangedResult = MediaOptimizeResultBase & {
  readonly status: 'unchanged';
  /** Echo of the validated original — required for unchanged. */
  readonly outputMimeType: string;
  readonly outputByteSize: number;
};

export type MediaOptimizeUnsupportedResult = MediaOptimizeResultBase & {
  readonly status: 'unsupported';
  readonly code: MediaOptimizeFailureCode;
  readonly message: string;
};

export type MediaOptimizeOverBudgetResult = MediaOptimizeResultBase & {
  readonly status: 'over-budget';
  readonly code: 'over-max-upload' | 'over-aggregate-budget';
  readonly message: string;
  readonly attemptedByteSize?: number;
};

export type MediaOptimizeAbortedResult = MediaOptimizeResultBase & {
  readonly status: 'aborted';
  readonly code: 'aborted';
  readonly message: string;
};

export type MediaOptimizeFailedResult = MediaOptimizeResultBase & {
  readonly status: 'failed';
  readonly code: MediaOptimizeFailureCode;
  readonly message: string;
};

export type ImageAssetPolicy = {
  readonly profileId: AssetProfileId;
  readonly kind: 'image';
  readonly allowedMimeTypes: readonly string[];
  readonly budget: MediaByteBudget;
  /** Soft max dimension hint for later engines (not a hard encode floor here). */
  readonly maxEdgePx: number;
  readonly minQuality: number;
  readonly preserveAlpha: boolean;
  readonly gifAnimation: GifAnimationPolicy;
  /** When false, engines must not emit WebP until coordinated migration completes. */
  readonly allowWebpOutput: boolean;
  readonly maxImagesPerRequest?: number;
  /** Hard aggregate JSON/Base64 request ceiling (Look analysis). */
  readonly maxAggregateRequestBytes?: number;
};

export type UnsupportedKindPolicy = {
  readonly profileId: AssetProfileId;
  readonly kind: Exclude<MediaKind, 'image'>;
  readonly supported: false;
  readonly message: string;
};

export type MediaPolicyEvaluation =
  | { readonly ok: true; readonly policy: ImageAssetPolicy }
  | {
      readonly ok: false;
      readonly reason:
        | 'unsupported-mime'
        | 'over-max-upload'
        | 'gif-not-allowed'
        | 'animation-not-allowed'
        | 'too-many-images'
        | 'over-aggregate-budget';
      readonly message: string;
      readonly policy: ImageAssetPolicy;
    };

export type ParsedPublicResourceId = {
  kind: PublicResourceKind;
  prefix: PublicResourcePrefix;
  body: string;
  value: string;
};

export type ScreenOrModalSignals = {
  /** Reload should restore the same view. */
  needsReloadRestore: boolean;
  /** Browser back/forward should represent this step. */
  needsHistoryStep: boolean;
  /** View should be shareable as a link. */
  needsShareableLink: boolean;
  /** Resource has its own stable identity. */
  hasOwnResourceIdentity: boolean;
  /** User performs a longer / standalone task here. */
  isStandaloneTask: boolean;
  /** Regularly reachable via primary navigation. */
  isPrimaryNavTarget: boolean;
};

export type ProjectSessionLifecycleStatus =
  | 'scheduled'
  | 'active'
  | 'paused'
  | 'completed'
  | 'cancelled';

export type LiveViewTarget =
  | { kind: 'gamemaster' }
  | { kind: 'player'; characterPublicId: string }
  | { kind: 'player-resolve' }
  | { kind: 'display' }
  | { kind: 'forbidden'; reason: string };

export interface CharacterCreationOption {
  value: string;
  label: string;
}

export interface SagaTreeRaceOption extends CharacterCreationOption {
  value: SagaTreeRaceKey;
  description: string;
}

export interface SagaTreeAttributeDefinition {
  key: SagaTreeAttributeKey;
  label: string;
  shortLabel: string;
  description: string;
}

export interface SagaTreeCoreAbilityDefinition {
  name: string;
  rank: 'I';
  actionType: 'Passiv' | 'Hauptaktion';
  description: string;
  effect: string;
}

export interface SagaTreeArchetypeOption extends CharacterCreationOption {
  value: SagaTreeArchetypeKey;
  summary: string;
  /** What this archetype is and what choosing it changes at character creation. */
  description: string;
  skills: readonly SagaTreeSkillKey[];
  coreAbility: SagaTreeCoreAbilityDefinition;
}

export interface SagaTreeEssenceOption extends CharacterCreationOption {
  value: SagaTreeEssenceKey;
  summary: string;
  description: string;
}

export interface SagaTreeSkillDefinition {
  key: SagaTreeSkillKey;
  label: string;
  attribute: SagaTreeAttributeKey;
  summary: string;
  excludes?: string;
  specializations: readonly string[];
}

export interface SagaTreeSpeciesTraitDefinition {
  key: SagaTreeSpeciesTraitKey;
  label: string;
  cost: 1 | 2 | 3;
  description: string;
  detailLabel?: string;
  detailPlaceholder?: string;
  detailRequired?: boolean;
  available?: boolean;
  unavailableReason?: string;
}

export interface CharacterAbstractResources {
  current: AbstractResourceLevel;
  base?: AbstractResourceLevel;
}

export type AffordabilityKind =
  | 'allow-free'
  | 'require-purchase-choice'
  | 'blocked-needs-gift-override';

